 72	                    return 1;
 73	                }
 74	
 75	                var distinctColumns = args.Skip(2).ToArray();
 76	                CsvRoundTripper.WriteDistinctRows(args[0], distinctColumns, outputStream);
 77	            }
 78	            else
 79	            {
