105	    public static void WriteSelectedColumns(string path, IReadOnlyList<string> selectedColumns, Stream output)
106	    {
107	        using var reader = new StreamReader(File.OpenRead(path));
108	        using var writer = new StreamWriter(output, leaveOpen: true)
109	        {
110	            NewLine = Environment.NewLine
111	        };
112	
113	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
114	        var headers = ParseCsvLine(headerLine);
115	        var headerIndexes = headers
116	            .Select((header, index) => new { header, index })
117	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
118	
119	        var selectedIndexes = selectedColumns
120	            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
121	                ? index
122	                : throw new InvalidOperationException($"Column not found: {columnName}"))
123	            .ToArray();
124	
125	        writer.WriteLine(string.Join(",", selectedColumns));
126	
127	        string? line;
128	        while ((line = reader.ReadLine()) is not null)
129	        {
130	            if (line.Length == 0)
131	            {
132	                writer.WriteLine();
133	                continue;
134	            }
135	
136	            var values = ParseCsvLine(line);
137	            var projectedValues = selectedIndexes.Select(index => index < values.Count ? values[index] : string.Empty);
138	            writer.WriteLine(string.Join(",", projectedValues));
139	        }
140	
141	        writer.Flush();
142	    }
