186	    public static void WriteSortedRows(string path, string columnName, string direction, Stream output)
187	    {
188	        var descending = ParseSortDirection(direction);
189	
190	        using var reader = new StreamReader(File.OpenRead(path));
191	        using var writer = new StreamWriter(output, leaveOpen: true)
192	        {
193	            NewLine = Environment.NewLine
194	        };
195	
196	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
197	        var headers = ParseCsvLine(headerLine);
198	        var headerIndexes = headers
199	            .Select((header, index) => new { header, index })
200	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
201	
202	        if (!headerIndexes.TryGetValue(columnName, out var sortColumnIndex))
203	        {
204	            throw new InvalidOperationException($"Column not found: {columnName}");
205	        }
206	
207	        var rows = new List<SortableRow>();
208	        var rowIndex = 0;
209	        var allNumeric = true;
210	
211	        string? line;
212	        while ((line = reader.ReadLine()) is not null)
213	        {
214	            if (line.Length == 0)
215	            {
216	                continue;
217	            }
218	
219	            var values = ParseCsvLine(line);
220	            var sortValue = GetValue(values, sortColumnIndex);
221	            if (!TryParseNumber(sortValue, out var numericSortValue))
222	            {
223	                allNumeric = false;
224	            }
225	
226	            rows.Add(new SortableRow(
227	                line,
228	                sortValue,
229	                numericSortValue,
230	                rowIndex++));
231	        }
232	
233	        writer.WriteLine(headerLine);
234	
235	        IEnumerable<SortableRow> orderedRows;
236	        if (allNumeric)
237	        {
238	            orderedRows = descending
239	                ? rows.OrderByDescending(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex)
240	                : rows.OrderBy(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex);
241	        }
242	        else
243	        {
244	            orderedRows = descending
245	                ? rows.OrderByDescending(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex)
246	                : rows.OrderBy(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex);
247	        }
248	
249	        foreach (var row in orderedRows)
250	        {
251	            writer.WriteLine(row.Line);
252	        }
253	
254	        writer.Flush();
255	    }
