289	    public static void WriteDistinctRows(string path, IReadOnlyList<string> distinctColumns, Stream output)
290	    {
291	        if (distinctColumns.Count == 0)
292	        {
293	            throw new InvalidOperationException("At least one column must be specified");
294	        }
295	
296	        using var reader = new StreamReader(File.OpenRead(path));
297	        using var writer = new StreamWriter(output, leaveOpen: true)
298	        {
299	            NewLine = Environment.NewLine
300	        };
301	
302	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
303	        var headers = ParseCsvLine(headerLine);
304	        var headerIndexes = headers
305	            .Select((header, index) => new { header, index })
306	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
307	
308	        var distinctIndexes = distinctColumns
309	            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
310	                ? index
311	                : throw new InvalidOperationException($"Column not found: {columnName}"))
312	            .ToArray();
313	
314	        writer.WriteLine(string.Join(",", distinctColumns));
315	
316	        var seenKeys = new HashSet<string[]>(new StringArrayComparer());
317	        string? line;
318	        while ((line = reader.ReadLine()) is not null)
319	        {
320	            if (line.Length == 0)
321	            {
322	                continue;
323	            }
324	
325	            var values = ParseCsvLine(line);
326	            var key = distinctIndexes.Select(index => GetValue(values, index)).ToArray();
327	            if (!seenKeys.Add(key))
328	            {
329	                continue;
330	            }
331	
332	            var projectedValues = distinctIndexes.Select(index => GetValue(values, index));
333	            writer.WriteLine(string.Join(",", projectedValues));
334	        }
335	
336	        writer.Flush();
337	    }
