344	    private static bool Matches(string leftValue, ComparisonOperator op, string rightValue)
345	    {
346	        if (TryParseNumber(leftValue, out var leftNumber) && TryParseNumber(rightValue, out var rightNumber))
347	        {
348	            return op switch
349	            {
350	                ComparisonOperator.Equal => leftNumber == rightNumber,
351	                ComparisonOperator.NotEqual => leftNumber != rightNumber,
352	                ComparisonOperator.GreaterThan => leftNumber > rightNumber,
353	                ComparisonOperator.LessThan => leftNumber < rightNumber,
354	                ComparisonOperator.GreaterThanOrEqual => leftNumber >= rightNumber,
355	                ComparisonOperator.LessThanOrEqual => leftNumber <= rightNumber,
356	                _ => throw new ArgumentOutOfRangeException(nameof(op), op, null)
357	            };
358	        }
359	
360	        var comparison = string.CompareOrdinal(leftValue, rightValue);
361	        return op switch
362	        {
363	            ComparisonOperator.Equal => comparison == 0,
364	            ComparisonOperator.NotEqual => comparison != 0,
365	            ComparisonOperator.GreaterThan => comparison > 0,
366	            ComparisonOperator.LessThan => comparison < 0,
367	            ComparisonOperator.GreaterThanOrEqual => comparison >= 0,
368	            ComparisonOperator.LessThanOrEqual => comparison <= 0,
369	            _ => throw new ArgumentOutOfRangeException(nameof(op), op, null)
370	        };
371	    }
